@st.cache_data(ttl=3600,show_spinner=False)
def canary():
    raw=yf.download(["QQQ","TIP"],period="3y",auto_adjust=False,progress=False,threads=False)
    p=raw["Close"] if isinstance(raw.columns,pd.MultiIndex) else raw
    vals={}
    for t in ["QQQ","TIP"]:
        s=p[t].dropna()
        vals[t]=float(np.mean([s.iloc[-1]/s.shift(n).iloc[-1]-1 for n in [21,63,126,252]]))
    return p.index[-1],vals,("공격 모드" if vals["QQQ"]>0 and vals["TIP"]>0 else "방어 모드")

@st.cache_data(ttl=3600,show_spinner=False)
def trend_backtest():
    tickers=["QQQ","SOXX","QLD","PSQ","GLD","SPMO","TIP"]
    today=datetime.today()
    first=today.replace(day=1)
    last_complete=first-timedelta(days=1)
    raw=yf.download(tickers,start="2010-01-01",end=last_complete.strftime("%Y-%m-%d"),
                    interval="1mo",auto_adjust=False,progress=False)
    p=raw["Close"].dropna(how="all")
    if isinstance(p.columns,pd.MultiIndex): p.columns=p.columns.droplevel(0)
    q=p["QQQ"].dropna(); tip=p["TIP"].dropna()
    qma=q.rolling(6).mean(); tma=tip.rolling(6).mean()
    up=(q>qma)&(tip>tma)
    d=up.dropna().index[-1]; is_up=bool(up.loc[d])
    alloc="QQQ 60% · QLD 15% · SOXX 25%" if is_up else "SPMO 50% · PSQ 50%"
    mr=p.pct_change().dropna()
    sig=up.shift(1).dropna()
    w=pd.DataFrame(0.0,index=mr.index,columns=mr.columns)
    for date in w.index:
        if date not in sig.index: continue
        if bool(sig.loc[date]):
            for t,x in [("QQQ",.60),("QLD",.15),("SOXX",.25)]:
                if t in w.columns:w.loc[date,t]=x
        else:
            for t,x in [("SPMO",.50),("PSQ",.50)]:
                if t in w.columns:w.loc[date,t]=x
    shifted=w.shift(1).dropna()
    pr=(shifted*mr).sum(axis=1)
    cum=(1+pr).cumprod()
    years=len(cum)/12
    cagr=float(cum.iloc[-1]**(1/years)-1)
    dd=cum/cum.cummax()-1; mdd=float(dd.min())
    qret=mr["QQQ"].reindex(cum.index).fillna(0)
    qcum=(1+qret).cumprod()
    return d,is_up,alloc,float(q.loc[d]),float(qma.loc[d]),float(tip.loc[d]),float(tma.loc[d]),cum,qcum,cagr,mdd


KR_SECTOR_SRC='# -*- coding: utf-8 -*-\n# ============================================================\n# ETF/섹터 분석 코드\n# - 6개월 Mansfield RS\n# - 6개월 변동성 조정 모멘텀\n# - 6개월 Sortino / ETR Comfort\n# - 업종 쏠림지수\n# - 최종 그래프: Sortino 10주선(50일선) 이상 섹터만\n#   30일 이격도 + 과거 247거래일 97% 초과 이격도 비교\n# ============================================================\n\n# ----------------------------\n# 1. 라이브러리 임포트\n# ----------------------------\nimport pandas as pd\nimport numpy as np\nimport io\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mticker\nimport logging\n\n# Matplotlib 한글 폰트 경고 숨김: 그래프는 영문/숫자 중심으로 표기\nlogging.getLogger(\'matplotlib.font_manager\').setLevel(logging.ERROR)\nplt.rcParams[\'axes.unicode_minus\'] = False\n\n# ------------------------------------------------------------\n# 참고\n# 그래프에서 한글 폰트가 깨질 수 있으므로,\n# 최종 그래프의 제목/범례는 영어로 표시합니다.\n# 한글 설명은 DataFrame 표로 표시하므로 깨지지 않습니다.\n# ------------------------------------------------------------\n\n# ----------------------------\n# 2. 엑셀 업로드 및 불러오기\n# ----------------------------\n\ndf = pd.read_excel(io.BytesIO(EXCEL_BYTES), sheet_name="데이터")\n\n# ----------------------------\n# 3. 데이터 전처리\n# ----------------------------\ndf = df.dropna(subset=[\'DATE\'])\ndf[\'DATE\'] = pd.to_datetime(df[\'DATE\'])\ndf.set_index(\'DATE\', inplace=True)\n\nkospi = df[\'코스피\'].dropna()\netf_data = df.drop(columns=[\'코스피\'])\n\n# ----------------------------\n# 4. Mansfield RS 계산 함수\n# ----------------------------\ndef compute_mansfield_rs(etf, benchmark, ma_period=52):\n    """\n    etf와 benchmark(코스피)의 비율(relative)을 ma_period 이동평균으로 나눈 편차(%)를 Mansfield RS로 계산\n    Note: 일간 데이터 기준 ma_period=52면 52일 이동평균\n    """\n    relative = etf / benchmark\n    ma = relative.rolling(window=ma_period, min_periods=ma_period).mean()\n    rs = ((relative / ma) - 1) * 100\n    return rs\n\n\ndef normalize_to_100_scale(x, scale=12):\n    """\n    Mansfield RS(%)를 0~100 스케일로 변환 (시그모이드)\n    scale이 작을수록 민감도 증가\n    """\n    return 100 * (1 / (1 + np.exp(-x / scale)))\n\n# ----------------------------\n# 5. RS 계산 실행 (6개월 = 126거래일)\n# ----------------------------\nRS_WINDOWS = [126]\n\nmansfield_rows = []\n\nfor column in etf_data.columns:\n    series = etf_data[column].dropna()\n    common_idx = series.index.intersection(kospi.index)\n    etf_series = series.loc[common_idx]\n    kospi_series = kospi.loc[common_idx]\n\n    if len(etf_series) < min(RS_WINDOWS):\n        continue\n\n    latest = {}\n\n    for win in RS_WINDOWS:\n        if len(etf_series) >= win:\n            rs_series = compute_mansfield_rs(etf_series, kospi_series, ma_period=win).dropna()\n            if not rs_series.empty:\n                raw = float(rs_series.iloc[-1])\n                latest[f"RS_{win}d"] = round(raw, 2)\n                latest[f"Norm_RS_{win}d"] = round(normalize_to_100_scale(raw), 2)\n\n    raw_keys = [k for k in latest.keys() if k.startswith("RS_") and k.endswith("d")]\n    if len(raw_keys) == 0:\n        continue\n\n    raw_values = [latest[k] for k in raw_keys]\n    rs_avg = round(sum(raw_values) / len(raw_values), 2)\n    norm_rs_avg = round(normalize_to_100_scale(rs_avg), 2)\n\n    row = {\n        "ETF": column,\n        "RS_126d": np.nan,\n        "Norm_RS_126d": np.nan,\n        "RS_avg": rs_avg,\n        "Norm_RS_avg": norm_rs_avg,\n    }\n\n    for win in RS_WINDOWS:\n        if f"RS_{win}d" in latest:\n            row[f"RS_{win}d"] = latest[f"RS_{win}d"]\n            row[f"Norm_RS_{win}d"] = latest[f"Norm_RS_{win}d"]\n\n    mansfield_rows.append(row)\n\nmansfield_df = pd.DataFrame(mansfield_rows).sort_values(by="Norm_RS_avg", ascending=False)\n\n# ----------------------------\n# 6. 변동성 조정 모멘텀 계산 함수\n# ----------------------------\ndef calculate_risk_adjusted_momentum(data, last_n_days=10, ma_filter_days=None, top_n=20):\n    """\n    최근 6개월(126거래일) 누적수익률을\n    같은 기간의 일간수익률 표준편차로 나눈 6개월 위험조정 모멘텀 점수.\n\n    score = 6개월 누적수익률 / 6개월 일간수익률 표준편차\n\n    ma_filter_days가 주어지면 해당 이동평균 하회 종목 제외.\n    """\n    daily_top = {}\n    trading_days = data.dropna(how=\'all\').index[-last_n_days:]\n\n    for day in trading_days:\n        if day not in data.index:\n            continue\n\n        end_idx = data.index.get_indexer_for([day])[0]\n        start_6m = max(0, end_idx - 125)\n        window_6m = data.iloc[start_6m:end_idx + 1]\n\n        # 6개월 누적수익률\n        returns_6m = (\n            window_6m.iloc[-1] / window_6m.iloc[0] - 1\n        )\n\n        # 6개월 일간수익률 변동성\n        daily_returns_6m = window_6m.pct_change(fill_method=None)\n        vol_6m = daily_returns_6m.std(skipna=True)\n\n        valid = (\n            returns_6m.notna()\n            & vol_6m.notna()\n            & (vol_6m > 0)\n        )\n\n        if ma_filter_days is not None:\n            ma_ok = []\n            for col in data.columns:\n                series = data[col].iloc[:end_idx + 1].dropna()\n                if len(series) < ma_filter_days:\n                    ma_ok.append(False)\n                else:\n                    ma_value = series.rolling(\n                        window=ma_filter_days\n                    ).mean().iloc[-1]\n                    price_value = series.iloc[-1]\n                    ma_ok.append(price_value >= ma_value)\n\n            ma_ok = pd.Series(ma_ok, index=data.columns)\n            valid &= ma_ok\n\n        risk_adj = (\n            returns_6m[valid] / vol_6m[valid]\n        )\n\n        top_list = (\n            risk_adj\n            .sort_values(ascending=False)\n            .head(top_n)\n            .index\n            .tolist()\n        )\n\n        while len(top_list) < top_n:\n            top_list.append(None)\n\n        daily_top[day] = top_list\n\n    df_top = pd.DataFrame.from_dict(\n        daily_top,\n        orient="index",\n        columns=[f"Top {i+1}" for i in range(top_n)]\n    )\n    df_top.index.name = "Date"\n    return df_top\n\n# ============================================================\n# 7. Sortino / ETR Comfort 계산 함수\n# ============================================================\ndef _mdd_from_returns(ret: pd.Series) -> float:\n    cum = (1 + ret.fillna(0)).cumprod()\n    peak = cum.cummax()\n    dd = (cum - peak) / peak\n    return float(dd.min())\n\n\ndef _sortino_from_returns(ret: pd.Series, mar: float = 0.0, periods_per_year: int = 252) -> float:\n    ret = ret.dropna()\n    if len(ret) < 5:\n        return np.nan\n\n    mar_daily = (1 + mar) ** (1 / periods_per_year) - 1\n    excess = ret - mar_daily\n    downside = excess[excess < 0]\n\n    if len(downside) < 5:\n        return np.nan\n\n    downside_dev = downside.std(ddof=1) * np.sqrt(periods_per_year)\n    if downside_dev == 0 or np.isnan(downside_dev):\n        return np.nan\n\n    annual_excess = excess.mean() * periods_per_year\n    return float(annual_excess / downside_dev)\n\n\ndef _cagr_from_prices_window(prices: pd.Series, periods_per_year: int = 252) -> float:\n    prices = prices.dropna()\n    if len(prices) < 2:\n        return np.nan\n\n    n = len(prices)\n    return float((prices.iloc[-1] / prices.iloc[0]) ** (periods_per_year / (n - 1)) - 1)\n\n\ndef _etr_comfort_from_prices_window(prices: pd.Series, periods_per_year: int = 252) -> float:\n    prices = prices.dropna()\n    if len(prices) < 60:\n        return np.nan\n\n    ret = prices.pct_change(fill_method=None).dropna()\n    if len(ret) < 5:\n        return np.nan\n\n    cagr = _cagr_from_prices_window(prices, periods_per_year=periods_per_year)\n    vol = float(ret.std(ddof=1) * np.sqrt(periods_per_year))\n    mdd = _mdd_from_returns(ret)\n    denom = abs(mdd) * vol\n\n    if denom == 0 or np.isnan(denom) or np.isnan(cagr):\n        return np.nan\n\n    return float(cagr / denom)\n\n\ndef _ma_ok_mask(close_df: pd.DataFrame, end_idx: int, ma_days: int) -> pd.Series:\n    ok = {}\n    for col in close_df.columns:\n        s = close_df[col].iloc[:end_idx + 1].dropna()\n        if len(s) < ma_days:\n            ok[col] = False\n        else:\n            ma = s.rolling(ma_days).mean().iloc[-1]\n            ok[col] = bool(s.iloc[-1] >= ma)\n    return pd.Series(ok)\n\n\ndef rank_sortino_or_etr_like_momentum(\n    data: pd.DataFrame,\n    metric: str = "sortino",\n    last_n_days: int = 10,\n    ma_filter_days: int = 10,\n    top_n: int = 20,\n    mar: float = 0.0,\n    periods_per_year: int = 252,\n    period_6m: int = 126,\n) -> pd.DataFrame:\n    """\n    최근 6개월(126거래일)만 사용해 Sortino 또는 ETR Comfort 순위를 계산합니다.\n    """\n\n    daily_top = {}\n    trading_days = data.dropna(how="all").index[-last_n_days:]\n\n    for day in trading_days:\n        end_idx = data.index.get_indexer_for([day])[0]\n        ok = _ma_ok_mask(\n            data,\n            end_idx=end_idx,\n            ma_days=ma_filter_days\n        )\n\n        scores = {}\n\n        for col in data.columns:\n            if not ok.get(col, False):\n                continue\n\n            start_idx = max(\n                0,\n                end_idx - (period_6m - 1)\n            )\n\n            w_prices = (\n                data[col]\n                .iloc[start_idx:end_idx + 1]\n                .dropna()\n            )\n\n            if len(w_prices) < max(\n                20,\n                int(period_6m * 0.8)\n            ):\n                continue\n\n            if metric == "sortino":\n                r = (\n                    w_prices\n                    .pct_change(fill_method=None)\n                    .dropna()\n                )\n                score = _sortino_from_returns(\n                    r,\n                    mar=mar,\n                    periods_per_year=periods_per_year\n                )\n\n            elif metric == "etr":\n                score = _etr_comfort_from_prices_window(\n                    w_prices,\n                    periods_per_year=periods_per_year\n                )\n\n            else:\n                raise ValueError(\n                    "metric은 \'sortino\' 또는 \'etr\'만 지원합니다."\n                )\n\n            if pd.notna(score):\n                scores[col] = float(score)\n\n        if len(scores) == 0:\n            daily_top[day] = [None] * top_n\n            continue\n\n        ranked = (\n            pd.Series(scores)\n            .sort_values(ascending=False)\n            .head(top_n)\n            .index\n            .tolist()\n        )\n\n        while len(ranked) < top_n:\n            ranked.append(None)\n\n        daily_top[day] = ranked\n\n    out = pd.DataFrame.from_dict(\n        daily_top,\n        orient="index",\n        columns=[f"Top {i+1}" for i in range(top_n)]\n    )\n    out.index.name = "Date"\n    return out\n\n# ----------------------------\n# 8. 기본 출력 테이블\n# ----------------------------\nmomentum_df = calculate_risk_adjusted_momentum(etf_data, last_n_days=10, ma_filter_days=None, top_n=20)\nprint("\\n📌 최근 10일간 변동성 조정 모멘텀 Top 20 ETF (전체):")\ndisplay(momentum_df)\n\nmomentum_df_ma10 = calculate_risk_adjusted_momentum(etf_data, last_n_days=10, ma_filter_days=10, top_n=20)\nprint("\\n📌 최근 10일간 변동성 조정 모멘텀 Top 20 ETF (10일선 이상):")\ndisplay(momentum_df_ma10)\n\nmomentum_df_ma20 = calculate_risk_adjusted_momentum(etf_data, last_n_days=10, ma_filter_days=20, top_n=20)\nprint("\\n📌 최근 10일간 변동성 조정 모멘텀 Top 20 ETF (20일선 이상):")\ndisplay(momentum_df_ma20)\n\nmomentum_df_ma10w = calculate_risk_adjusted_momentum(etf_data, last_n_days=10, ma_filter_days=50, top_n=20)\nprint("\\n📌 최근 10일간 변동성 조정 모멘텀 Top 20 ETF (10주선(50일) 이상):")\ndisplay(momentum_df_ma10w)\n\nsortino_ma10 = rank_sortino_or_etr_like_momentum(etf_data, metric="sortino", last_n_days=10, ma_filter_days=10, top_n=20)\nprint("\\n📌 최근 10일간 Sortino Top 20 ETF (10일선 이상 / 6M):")\ndisplay(sortino_ma10)\n\nsortino_ma20 = rank_sortino_or_etr_like_momentum(etf_data, metric="sortino", last_n_days=10, ma_filter_days=20, top_n=20)\nprint("\\n📌 최근 10일간 Sortino Top 20 ETF (20일선 이상 / 6M):")\ndisplay(sortino_ma20)\n\nsortino_ma10w = rank_sortino_or_etr_like_momentum(etf_data, metric="sortino", last_n_days=10, ma_filter_days=50, top_n=20)\nprint("\\n📌 최근 10일간 Sortino Top 20 ETF (10주선(50일) 이상 / 6M):")\ndisplay(sortino_ma10w)\n\netr_ma10 = rank_sortino_or_etr_like_momentum(etf_data, metric="etr", last_n_days=10, ma_filter_days=10, top_n=20)\nprint("\\n📌 최근 10일간 ETR Comfort Top 20 ETF (10일선 이상 / 6M):")\ndisplay(etr_ma10)\n\netr_ma20 = rank_sortino_or_etr_like_momentum(etf_data, metric="etr", last_n_days=10, ma_filter_days=20, top_n=20)\nprint("\\n📌 최근 10일간 ETR Comfort Top 20 ETF (20일선 이상 / 6M):")\ndisplay(etr_ma20)\n\netr_ma10w = rank_sortino_or_etr_like_momentum(etf_data, metric="etr", last_n_days=10, ma_filter_days=50, top_n=20)\nprint("\\n📌 최근 10일간 ETR Comfort Top 20 ETF (10주선(50일) 이상 / 6M):")\ndisplay(etr_ma10w)\n\nprint("\\n📌 Mansfield RS (126일(6개월)) 결과 (Norm_RS_avg 내림차순):")\ndisplay(mansfield_df)\n\n\n# ------------------------------------------------------------\n# 6개월 절대수익률 + 6개월 KOSPI 대비 상대수익률 표\n# ------------------------------------------------------------\nLOOKBACK_6M = 126\n\nreturn_6m = (\n    etf_data / etf_data.shift(LOOKBACK_6M) - 1\n)\n\nkospi_return_6m = (\n    kospi / kospi.shift(LOOKBACK_6M) - 1\n)\n\nrelative_return_6m = return_6m.sub(\n    kospi_return_6m,\n    axis=0\n)\n\nlatest_6m_date = return_6m.dropna(how="all").index[-1]\n\nsix_month_summary = pd.DataFrame({\n    "6M_Return": return_6m.loc[latest_6m_date],\n    "6M_RS_vs_KOSPI": relative_return_6m.loc[latest_6m_date],\n}).dropna()\n\nsix_month_summary = six_month_summary.sort_values(\n    "6M_RS_vs_KOSPI",\n    ascending=False\n)\n\nprint(\n    f"\\n📌 기준일 {latest_6m_date.date()} "\n    f"6개월 수익률 및 KOSPI 대비 RS"\n)\n\ndisplay(\n    six_month_summary.style.format({\n        "6M_Return": "{:.2%}",\n        "6M_RS_vs_KOSPI": "{:+.2%}",\n    })\n)\n\nmansfield_df_70 = mansfield_df[mansfield_df["Norm_RS_avg"] >= 70].copy()\nprint("\\n📌 Normalized RS 평균 ≥ 70 (필터링):")\ndisplay(mansfield_df_70)\n\n# ============================================================\n# 9. 업종(테마) 쏠림지수\n# ============================================================\ndef compute_crowding_index(\n    price_df: pd.DataFrame,\n    lookback_days: int = 126,\n    min_universe: int = 10,\n    score_mode: str = "linear",\n    scale: float = 100.0\n):\n    ret6m = price_df.pct_change(lookback_days, fill_method=None)\n\n    crowding_vals = []\n    valid_dates = ret6m.index\n\n    for dt in valid_dates:\n        r = ret6m.loc[dt].dropna()\n        n = len(r)\n        if n < min_universe:\n            crowding_vals.append(np.nan)\n            continue\n\n        rank = r.rank(ascending=False, method="average")\n\n        if score_mode == "linear":\n            score = (n - rank) / (n - 1)\n        elif score_mode == "centered":\n            score = ((n + 1) / 2 - rank) / ((n - 1) / 2)\n        else:\n            raise ValueError("score_mode는 \'linear\' 또는 \'centered\'만 지원합니다.")\n\n        weighted = score * r\n        crowd = float(weighted.std(ddof=1) * scale)\n        crowding_vals.append(crowd)\n\n    crowding_series = pd.Series(crowding_vals, index=valid_dates, name="CrowdingIndex").dropna()\n    return crowding_series, ret6m\n\n\ncrowding_series, ret6m = compute_crowding_index(\n    etf_data,\n    lookback_days=126,\n    min_universe=10,\n    score_mode="centered",\n    scale=100.0\n)\n\nprint("\\n📌 업종(테마) 쏠림지수(6개월 수익률 기반) 최신값:")\nlatest_dt = crowding_series.index[-1]\nlatest_crowd = crowding_series.iloc[-1]\nprint(f"- Date: {latest_dt.date()}  |  CrowdingIndex: {latest_crowd:.2f}")\nprint("  (참고: 35 이상을 과열/쏠림 신호로 참고)")\ndisplay(crowding_series.tail(20))\n\n\ndef show_leaders_laggards(ret6m: pd.DataFrame, date: pd.Timestamp, top_k: int = 10):\n    r = ret6m.loc[date].dropna().sort_values(ascending=False)\n\n    top = r.head(top_k)\n    bottom = r.tail(top_k).sort_values(ascending=True)\n\n    print(f"\\n📈 주도 업종 Top {top_k} (6개월 수익률)")\n    display(top.to_frame("6M Return"))\n\n    print(f"\\n📉 소외 업종 Bottom {top_k} (6개월 수익률)")\n    display(bottom.to_frame("6M Return"))\n\n\nprint("\\n📌 최신일 기준 6개월 수익률 주도/소외 업종:")\nshow_leaders_laggards(ret6m, latest_dt, top_k=10)\n\nthreshold = 35.0\nsignal = "🔥 과열/쏠림" if latest_crowd >= threshold else "✅ 비과열/확산"\nprint(f"\\n📌 쏠림 판정: {signal} (threshold={threshold}, value={latest_crowd:.2f})")\n# ============================================================\n# 10. ETF/섹터 Breadth\n#     전체 ETF 중 이동평균선 위에 있는 종목 비율\n#\n#     Above MA10 : 10일선 위 종목 비율\n#     Above MA20 : 20일선 위 종목 비율\n#     Above MA50 : 10주선(50일선) 위 종목 비율\n# ============================================================\n\ndef compute_ma_breadth(\n    price_df: pd.DataFrame,\n    ma_windows=(10, 20, 50),\n    min_valid_assets=10,\n    smooth_days=3\n):\n    """\n    날짜별로 전체 ETF 중 각 이동평균선 위에 있는 종목 비율을 계산합니다.\n    """\n\n    price_df = price_df.sort_index().copy()\n    breadth_df = pd.DataFrame(index=price_df.index)\n\n    for window in ma_windows:\n\n        moving_average = price_df.rolling(\n            window=window,\n            min_periods=window\n        ).mean()\n\n        valid_mask = (\n            price_df.notna() &\n            moving_average.notna()\n        )\n\n        valid_count = valid_mask.sum(axis=1)\n\n        above_count = (\n            (price_df >= moving_average) &\n            valid_mask\n        ).sum(axis=1)\n\n        breadth_ratio = (\n            above_count /\n            valid_count.replace(0, np.nan) *\n            100\n        )\n\n        breadth_ratio = breadth_ratio.where(\n            valid_count >= min_valid_assets\n        )\n\n        breadth_df[f"Above_MA{window}"] = breadth_ratio\n        breadth_df[f"Count_Above_MA{window}"] = above_count\n        breadth_df[f"Valid_Count_MA{window}"] = valid_count\n\n        # 하루 단위 휩쏘 완화\n        breadth_df[f"Above_MA{window}_Smooth"] = (\n            breadth_ratio\n            .rolling(\n                smooth_days,\n                min_periods=1\n            )\n            .mean()\n        )\n\n    return breadth_df\n\n\n# ------------------------------------------------------------\n# Breadth 계산\n# ------------------------------------------------------------\nsector_breadth = compute_ma_breadth(\n    price_df=etf_data,\n    ma_windows=(10, 20, 50),\n    min_valid_assets=10,\n    smooth_days=3\n)\n\n\n# ------------------------------------------------------------\n# 종합 Breadth Score\n#\n# 10일선 35%\n# 20일선 35%\n# 10주선 30%\n# ------------------------------------------------------------\nsector_breadth["Breadth_Score"] = (\n    sector_breadth["Above_MA10_Smooth"] * 0.35 +\n    sector_breadth["Above_MA20_Smooth"] * 0.35 +\n    sector_breadth["Above_MA50_Smooth"] * 0.30\n)\n\nsector_breadth["Breadth_Score_MA5"] = (\n    sector_breadth["Breadth_Score"]\n    .rolling(5, min_periods=1)\n    .mean()\n)\n\nsector_breadth["Breadth_Slope_5D"] = (\n    sector_breadth["Breadth_Score_MA5"] -\n    sector_breadth["Breadth_Score_MA5"].shift(5)\n)\n\nsector_breadth["Breadth_Slope_10D"] = (\n    sector_breadth["Breadth_Score_MA5"] -\n    sector_breadth["Breadth_Score_MA5"].shift(10)\n)\n\n\n# ------------------------------------------------------------\n# 최신 Breadth 요약표\n# ------------------------------------------------------------\nvalid_breadth = sector_breadth.dropna(\n    subset=["Breadth_Score_MA5"]\n)\n\nlatest_breadth = valid_breadth.iloc[-1]\nlatest_breadth_date = valid_breadth.index[-1]\n\nbreadth_summary = pd.DataFrame({\n    "현재값": {\n        "10일선 위 종목 비율": latest_breadth["Above_MA10"],\n        "20일선 위 종목 비율": latest_breadth["Above_MA20"],\n        "10주선(50일선) 위 종목 비율": latest_breadth["Above_MA50"],\n        "종합 Breadth Score": latest_breadth["Breadth_Score_MA5"],\n        "Breadth 5일 변화": latest_breadth["Breadth_Slope_5D"],\n        "Breadth 10일 변화": latest_breadth["Breadth_Slope_10D"],\n    }\n})\n\nprint(f"\\n📌 ETF/섹터 Breadth 기준일: {latest_breadth_date.date()}")\n\ndisplay(\n    breadth_summary.style.format("{:.1f}")\n)\n\n\n# ------------------------------------------------------------\n# 최신 이동평균선 위 종목 수\n# ------------------------------------------------------------\nlatest_count_table = pd.DataFrame({\n    "이동평균": [\n        "MA10 (10일선)",\n        "MA20 (20일선)",\n        "MA50 (10주선)"\n    ],\n    "이평선 위 종목 수": [\n        int(latest_breadth["Count_Above_MA10"]),\n        int(latest_breadth["Count_Above_MA20"]),\n        int(latest_breadth["Count_Above_MA50"]),\n    ],\n    "분석 가능 종목 수": [\n        int(latest_breadth["Valid_Count_MA10"]),\n        int(latest_breadth["Valid_Count_MA20"]),\n        int(latest_breadth["Valid_Count_MA50"]),\n    ],\n    "Breadth 비율": [\n        latest_breadth["Above_MA10"],\n        latest_breadth["Above_MA20"],\n        latest_breadth["Above_MA50"],\n    ]\n})\n\nprint("\\n📌 현재 이동평균선 위 ETF/섹터 수")\n\ndisplay(\n    latest_count_table.style.format({\n        "Breadth 비율": "{:.1f}%"\n    })\n)\n\n\n# ------------------------------------------------------------\n# 그래프 1: 10일선·20일선·10주선 Breadth\n# ------------------------------------------------------------\nplt.figure(figsize=(16, 6))\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Above_MA10_Smooth"],\n    linewidth=1.8,\n    label="Above MA10"\n)\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Above_MA20_Smooth"],\n    linewidth=2.0,\n    label="Above MA20"\n)\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Above_MA50_Smooth"],\n    linewidth=2.3,\n    label="Above MA50 (10 Weeks)"\n)\n\nplt.axhline(70, linestyle="--", alpha=0.5)\nplt.axhline(50, linestyle="--", alpha=0.5)\nplt.axhline(30, linestyle="--", alpha=0.5)\n\nplt.title("ETF Sector Moving Average Breadth")\nplt.ylabel("Sectors Above Moving Average (%)")\nplt.ylim(0, 100)\nplt.legend(loc="best")\nplt.grid(alpha=0.25)\n\nplt.tight_layout()\nplt.show()\n\n\n# ------------------------------------------------------------\n# 그래프 2: 종합 Breadth Score\n# ------------------------------------------------------------\nplt.figure(figsize=(16, 6))\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Breadth_Score"],\n    alpha=0.35,\n    linewidth=1.2,\n    label="Daily Breadth Score"\n)\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Breadth_Score_MA5"],\n    linewidth=2.4,\n    label="Breadth Score MA5"\n)\n\nplt.axhline(70, linestyle="--", alpha=0.5)\nplt.axhline(60, linestyle="--", alpha=0.5)\nplt.axhline(50, linestyle="--", alpha=0.5)\nplt.axhline(35, linestyle="--", alpha=0.5)\n\nplt.title("ETF Sector Breadth Score")\nplt.ylabel("Breadth Score")\nplt.ylim(0, 100)\nplt.legend(loc="best")\nplt.grid(alpha=0.25)\n\nplt.tight_layout()\nplt.show()\n\n\n# ------------------------------------------------------------\n# 그래프 3: Breadth 기울기\n# ------------------------------------------------------------\nplt.figure(figsize=(16, 5))\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Breadth_Slope_5D"],\n    linewidth=1.8,\n    label="5D Breadth Slope"\n)\n\nplt.plot(\n    sector_breadth.index,\n    sector_breadth["Breadth_Slope_10D"],\n    linewidth=1.8,\n    label="10D Breadth Slope"\n)\n\nplt.axhline(0, linewidth=1)\nplt.axhline(10, linestyle="--", alpha=0.5)\nplt.axhline(-10, linestyle="--", alpha=0.5)\n\nplt.title("ETF Sector Breadth Slope")\nplt.ylabel("Score Change")\nplt.legend(loc="best")\nplt.grid(alpha=0.25)\n\nplt.tight_layout()\nplt.show()\n\n\n# ------------------------------------------------------------\n# 최근 20거래일 Breadth 변화표\n# ------------------------------------------------------------\nrecent_breadth_cols = [\n    "Above_MA10",\n    "Above_MA20",\n    "Above_MA50",\n    "Breadth_Score_MA5",\n    "Breadth_Slope_5D",\n    "Breadth_Slope_10D"\n]\n\nprint("\\n📌 최근 20거래일 ETF/섹터 Breadth")\n\ndisplay(\n    sector_breadth[recent_breadth_cols]\n    .tail(20)\n    .style\n    .format({\n        "Above_MA10": "{:.1f}",\n        "Above_MA20": "{:.1f}",\n        "Above_MA50": "{:.1f}",\n        "Breadth_Score_MA5": "{:.1f}",\n        "Breadth_Slope_5D": "{:+.1f}",\n        "Breadth_Slope_10D": "{:+.1f}"\n    })\n)\n# ============================================================\n# 11. 최종 그래프\n#     Sortino 10주선(50일선) 이상 섹터만 출력\n#     30일 이격도 + 과거 247거래일 97% 초과 이격도 비교\n#\n#     구성:\n#     1) 먼저 전체 요약표 1개 출력\n#     2) 그 다음 섹터별 가로형 그래프 출력\n#     3) 그래프에는 한글을 최소화하여 폰트 깨짐 방지\n# ============================================================\n\nLOOKBACK_DAYS = 247    # 최근 247거래일 기준\nGAP_MA_DAYS = 30      # 30일 이격도\nGRAPH_YLIM = (90, 160)\nBAR_ALPHA = 0.15\n\n\ndef make_sortino_10w_gap30_summary(price_df: pd.DataFrame, sortino_top_df: pd.DataFrame) -> pd.DataFrame:\n    """\n    Sortino 10주선(50일선) 이상 섹터만 대상으로\n    30일 이격도와 과거 247거래일 97% 초과 이격도 수준을 계산합니다.\n\n    표시용 컬럼은 % 기호를 붙여 눈으로 보기 쉽게 만들고,\n    그래프 계산용 숫자 컬럼은 앞에 \'_\'를 붙여 내부용으로 보관합니다.\n    """\n    latest_sortino_list = sortino_top_df.iloc[-1].dropna().tolist()\n\n    summary_rows = []\n\n    for rank_no, sector in enumerate(latest_sortino_list, start=1):\n        if sector not in price_df.columns:\n            continue\n\n        price = price_df[sector].dropna()\n        if len(price) < GAP_MA_DAYS + 5:\n            continue\n\n        ma30 = price.rolling(GAP_MA_DAYS).mean()\n        gap30 = price / ma30 * 100\n        gap30 = gap30.dropna()\n\n        if gap30.empty:\n            continue\n\n        recent_gap = gap30.tail(LOOKBACK_DAYS)\n\n        current_price = float(price.loc[gap30.index[-1]])\n        current_ma30 = float(ma30.loc[gap30.index[-1]])\n        current_gap = float(gap30.iloc[-1])\n        current_gap_excess = current_gap - 100\n\n        gap97 = float(recent_gap.quantile(0.97))\n        gap97_excess = gap97 - 100\n\n        # 현재 위치: 30일선 초과분 기준으로 비교\n        # 예: 현재 초과분 12, 247거래일 97% 초과분 10이면 120%\n        excess_heat_ratio = (\n            current_gap_excess / gap97_excess * 100\n            if gap97_excess != 0\n            else np.nan\n        )\n\n        기준일 = gap30.index[-1].strftime("%Y-%m-%d")\n\n        summary_rows.append({\n            "Sortino순위": rank_no,\n            "섹터": sector,\n            "종가": f"{current_price:,.0f}",\n            "MA30": f"{current_ma30:,.0f}",\n            "현재30일선초과이격도": round(current_gap_excess, 2),\n            "247거래일97%초과이격도": round(gap97_excess, 2),\n            "97%구간대비현재위치": f"{excess_heat_ratio:.1f}%",\n            "기준일": 기준일,\n            # 그래프 제목용 내부 숫자 컬럼\n            "_현재30일선초과이격도": round(current_gap_excess, 2),\n            "_247거래일97%초과이격도": round(gap97_excess, 2),\n            "_97%구간대비현재위치": round(excess_heat_ratio, 1),\n        })\n\n    summary_df = pd.DataFrame(summary_rows)\n    return summary_df\n\n\ndef plot_gap30_charts_after_summary(price_df: pd.DataFrame, summary_df: pd.DataFrame):\n    """\n    표는 한글로 출력하고, 그래프 내부 텍스트는 영문/숫자 중심으로 표시합니다.\n    그래서 NanumGothic 폰트가 없어도 경고가 나오지 않습니다.\n    """\n    for _, row in summary_df.iterrows():\n        sector = row["섹터"]\n        rank_no = int(row["Sortino순위"])\n\n        if sector not in price_df.columns:\n            continue\n\n        price = price_df[sector].dropna()\n        ma30 = price.rolling(GAP_MA_DAYS).mean()\n        gap30 = price / ma30 * 100\n\n        plot_df = pd.DataFrame({\n            "Price": price,\n            "MA30": ma30,\n            "Gap30": gap30,\n        }).dropna()\n\n        if plot_df.empty:\n            continue\n\n        fig, ax1 = plt.subplots(figsize=(16, 4))\n        ax2 = ax1.twinx()\n\n        # 이격도 막대: 뒤쪽에 연하게 표시\n        ax2.bar(\n            plot_df.index,\n            plot_df["Gap30"],\n            color="#FFC000",\n            alpha=BAR_ALPHA,\n            width=1.5,\n            label="Gap30",\n            zorder=1,\n        )\n        ax2.set_ylim(GRAPH_YLIM)\n\n        # 왼쪽 축을 앞으로 가져오기\n        ax1.set_zorder(ax2.get_zorder() + 1)\n        ax1.patch.set_visible(False)\n\n        # 가격과 MA30\n        ax1.plot(\n            plot_df.index,\n            plot_df["Price"],\n            color="black",\n            linewidth=2.8,\n            label="Price",\n            zorder=10,\n        )\n\n        ax1.plot(\n            plot_df.index,\n            plot_df["MA30"],\n            color="#8FA3BD",\n            linewidth=3.0,\n            label="MA30",\n            zorder=9,\n        )\n\n        ax1.yaxis.set_major_formatter(mticker.StrMethodFormatter("{x:,.0f}"))\n        ax1.grid(True, axis="both", alpha=0.25, zorder=0)\n\n        # 그래프 제목은 영문/숫자 중심으로 표시해서 한글 폰트 깨짐 및 font warning 방지\n        ax1.set_title(\n            f"Sortino Rank #{rank_no} | Gap30 Excess={row[\'_현재30일선초과이격도\']:.1f} | P97 Excess={row[\'_247거래일97%초과이격도\']:.1f} | Heat={row[\'_97%구간대비현재위치\']:.1f}%",\n            fontsize=13,\n            fontweight="bold",\n        )\n\n        lines1, labels1 = ax1.get_legend_handles_labels()\n        lines2, labels2 = ax2.get_legend_handles_labels()\n\n        ax1.legend(\n            lines2 + lines1,\n            labels2 + labels1,\n            loc="upper center",\n            bbox_to_anchor=(0.5, 1.18),\n            ncol=3,\n            frameon=False,\n            fontsize=11,\n        )\n\n        plt.tight_layout()\n        plt.show()\n\n\n# ------------------------------------------------------------\n# 최종 실행\n# ------------------------------------------------------------\nsummary_df = make_sortino_10w_gap30_summary(\n    price_df=etf_data,\n    sortino_top_df=sortino_ma10w,\n)\n\nprint("\\n📌 Sortino 10주선(50일선) 이상 섹터: 30일선 초과 이격도 / 247거래일 97% 구간 비교")\ndisplay_cols = [c for c in summary_df.columns if not c.startswith("_")]\ndisplay(summary_df[display_cols])\n\nplot_gap30_charts_after_summary(\n    price_df=etf_data,\n    summary_df=summary_df,\n)\n\n\n# ============================================================\n# 12. 4주 / 13주 / 26주 / 52주 이동평균 정배열 종목군\n#\n# 일봉 데이터 기준:\n# 4주  = 20거래일\n# 13주 = 65거래일\n# 26주 = 130거래일\n# 52주 = 260거래일\n#\n# 완전 정배열:\n# 현재가 > MA20 > MA65 > MA130 > MA260\n#\n# 이평 정배열:\n# MA20 > MA65 > MA130 > MA260\n# ============================================================\n\nMA_4W = 20\nMA_13W = 65\nMA_26W = 130\nMA_52W = 260\n\n\ndef get_weekly_ma_alignment(price_df: pd.DataFrame) -> pd.DataFrame:\n    """\n    각 ETF/섹터별 최신 유효 시점에서\n    4주(20일), 13주(65일), 26주(130일), 52주(260일)\n    이동평균 정배열 여부를 계산합니다.\n    """\n\n    price_df = price_df.sort_index().copy()\n\n    ma4 = price_df.rolling(\n        window=MA_4W,\n        min_periods=MA_4W\n    ).mean()\n\n    ma13 = price_df.rolling(\n        window=MA_13W,\n        min_periods=MA_13W\n    ).mean()\n\n    ma26 = price_df.rolling(\n        window=MA_26W,\n        min_periods=MA_26W\n    ).mean()\n\n    ma52 = price_df.rolling(\n        window=MA_52W,\n        min_periods=MA_52W\n    ).mean()\n\n    result_rows = []\n\n    for col in price_df.columns:\n\n        temp = pd.DataFrame({\n            "Price": price_df[col],\n            "MA4W": ma4[col],\n            "MA13W": ma13[col],\n            "MA26W": ma26[col],\n            "MA52W": ma52[col],\n        }).dropna()\n\n        if temp.empty:\n            continue\n\n        latest_date = temp.index[-1]\n        row = temp.iloc[-1]\n\n        ma_alignment = (\n            row["MA4W"] > row["MA13W"]\n            and row["MA13W"] > row["MA26W"]\n            and row["MA26W"] > row["MA52W"]\n        )\n\n        full_alignment = (\n            row["Price"] > row["MA4W"]\n            and ma_alignment\n        )\n\n        # 정배열 간격 계산\n        gap_price_4w = (row["Price"] / row["MA4W"] - 1) * 100\n        gap_4w_13w = (row["MA4W"] / row["MA13W"] - 1) * 100\n        gap_13w_26w = (row["MA13W"] / row["MA26W"] - 1) * 100\n        gap_26w_52w = (row["MA26W"] / row["MA52W"] - 1) * 100\n\n        # 단순 정배열 강도:\n        # 각 이평선 간 양(+)의 간격이 클수록 높은 값\n        alignment_strength = (\n            gap_price_4w\n            + gap_4w_13w\n            + gap_13w_26w\n            + gap_26w_52w\n        )\n\n        result_rows.append({\n            "ETF": col,\n            "기준일": latest_date,\n            "현재가": float(row["Price"]),\n            "MA4주": float(row["MA4W"]),\n            "MA13주": float(row["MA13W"]),\n            "MA26주": float(row["MA26W"]),\n            "MA52주": float(row["MA52W"]),\n            "현재가>4주": bool(row["Price"] > row["MA4W"]),\n            "4주>13주": bool(row["MA4W"] > row["MA13W"]),\n            "13주>26주": bool(row["MA13W"] > row["MA26W"]),\n            "26주>52주": bool(row["MA26W"] > row["MA52W"]),\n            "이평정배열": bool(ma_alignment),\n            "완전정배열": bool(full_alignment),\n            "현재가_4주이격(%)": float(gap_price_4w),\n            "4주_13주이격(%)": float(gap_4w_13w),\n            "13주_26주이격(%)": float(gap_13w_26w),\n            "26주_52주이격(%)": float(gap_26w_52w),\n            "정배열강도": float(alignment_strength),\n        })\n\n    result_df = pd.DataFrame(result_rows)\n\n    if result_df.empty:\n        return result_df\n\n    return result_df.sort_values(\n        by="정배열강도",\n        ascending=False\n    ).reset_index(drop=True)\n\n\n# ------------------------------------------------------------\n# 정배열 계산\n# ------------------------------------------------------------\n\nweekly_alignment_df = get_weekly_ma_alignment(etf_data)\n\n\nif weekly_alignment_df.empty:\n\n    print("\\n⚠️ 4주·13주·26주·52주 정배열을 계산할 수 있는 충분한 데이터가 없습니다.")\n\nelse:\n\n    # --------------------------------------------------------\n    # ① 완전 정배열\n    # 현재가 > 4주 > 13주 > 26주 > 52주\n    # --------------------------------------------------------\n\n    full_alignment_df = (\n        weekly_alignment_df[\n            weekly_alignment_df["완전정배열"]\n        ]\n        .copy()\n        .sort_values(\n            by="정배열강도",\n            ascending=False\n        )\n        .reset_index(drop=True)\n    )\n\n    print(\n        "\\n📌 4주·13주·26주·52주 완전 정배열"\n        "\\n   현재가 > 4주선 > 13주선 > 26주선 > 52주선"\n    )\n\n    if full_alignment_df.empty:\n        print("해당 종목이 없습니다.")\n    else:\n        display(\n            full_alignment_df[\n                [\n                    "ETF",\n                    "기준일",\n                    "현재가",\n                    "MA4주",\n                    "MA13주",\n                    "MA26주",\n                    "MA52주",\n                    "현재가_4주이격(%)",\n                    "4주_13주이격(%)",\n                    "13주_26주이격(%)",\n                    "26주_52주이격(%)",\n                    "정배열강도",\n                ]\n            ].style.format({\n                "현재가": "{:,.2f}",\n                "MA4주": "{:,.2f}",\n                "MA13주": "{:,.2f}",\n                "MA26주": "{:,.2f}",\n                "MA52주": "{:,.2f}",\n                "현재가_4주이격(%)": "{:+.2f}%",\n                "4주_13주이격(%)": "{:+.2f}%",\n                "13주_26주이격(%)": "{:+.2f}%",\n                "26주_52주이격(%)": "{:+.2f}%",\n                "정배열강도": "{:.2f}",\n            })\n        )\n\n\n    # --------------------------------------------------------\n    # ② 이동평균선 자체 정배열\n    # 4주 > 13주 > 26주 > 52주\n    #\n    # 현재가가 4주선 아래여도 포함\n    # --------------------------------------------------------\n\n    ma_alignment_df = (\n        weekly_alignment_df[\n            weekly_alignment_df["이평정배열"]\n        ]\n        .copy()\n        .sort_values(\n            by="정배열강도",\n            ascending=False\n        )\n        .reset_index(drop=True)\n    )\n\n    print(\n        "\\n📌 이동평균 정배열 종목군"\n        "\\n   4주선 > 13주선 > 26주선 > 52주선"\n    )\n\n    if ma_alignment_df.empty:\n        print("해당 종목이 없습니다.")\n    else:\n        display(\n            ma_alignment_df[\n                [\n                    "ETF",\n                    "기준일",\n                    "현재가",\n                    "MA4주",\n                    "MA13주",\n                    "MA26주",\n                    "MA52주",\n                    "현재가>4주",\n                    "현재가_4주이격(%)",\n                    "4주_13주이격(%)",\n                    "13주_26주이격(%)",\n                    "26주_52주이격(%)",\n                    "정배열강도",\n                ]\n            ].style.format({\n                "현재가": "{:,.2f}",\n                "MA4주": "{:,.2f}",\n                "MA13주": "{:,.2f}",\n                "MA26주": "{:,.2f}",\n                "MA52주": "{:,.2f}",\n                "현재가_4주이격(%)": "{:+.2f}%",\n                "4주_13주이격(%)": "{:+.2f}%",\n                "13주_26주이격(%)": "{:+.2f}%",\n                "26주_52주이격(%)": "{:+.2f}%",\n                "정배열강도": "{:.2f}",\n            })\n        )\n\n\n    # --------------------------------------------------------\n    # ③ 단계별 정배열 상태표\n    # --------------------------------------------------------\n\n    print(\n        "\\n📌 전체 ETF/섹터 정배열 상태"\n    )\n\n    display(\n        weekly_alignment_df[\n            [\n                "ETF",\n                "기준일",\n                "현재가>4주",\n                "4주>13주",\n                "13주>26주",\n                "26주>52주",\n                "이평정배열",\n                "완전정배열",\n                "정배열강도",\n            ]\n        ].style.format({\n            "정배열강도": "{:.2f}",\n        })\n    )\n\n\n    # --------------------------------------------------------\n    # ④ 종목명만 간단 출력\n    # --------------------------------------------------------\n\n    print("\\n🔥 완전 정배열 종목:")\n    if len(full_alignment_df) > 0:\n        print(\n            " / ".join(\n                full_alignment_df["ETF"].astype(str).tolist()\n            )\n        )\n    else:\n        print("없음")\n\n\n    print("\\n📈 4·13·26·52주 이평 정배열 종목:")\n    if len(ma_alignment_df) > 0:\n        print(\n            " / ".join(\n                ma_alignment_df["ETF"].astype(str).tolist()\n            )\n        )\n    else:\n        print("없음")\n\n\n    print(\n        f"\\n📊 정배열 현황"\n        f"\\n- 완전 정배열: {len(full_alignment_df)}개"\n        f"\\n- 이평 정배열: {len(ma_alignment_df)}개"\n        f"\\n- 분석 가능 전체: {len(weekly_alignment_df)}개"\n    )'
US_SECTOR_SRC='# ----------------------------\n# 1. 라이브러리 설치 (Google Colab 전용)\n# ----------------------------\n\n# ----------------------------\n# 2. 라이브러리 임포트\n# ----------------------------\nimport yfinance as yf\nimport pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\n\n# ----------------------------\n# 3. 산업별 ETF 정의\n# ----------------------------\nindustry_etfs = {\n\n    # ------------------------------------------------\n    # 1. 벤치마크\n    # ------------------------------------------------\n    "SPY": "S&P 500",\n\n    # ------------------------------------------------\n    # 2. 미국 기본 11개 섹터 (대표 ETF)\n    # ------------------------------------------------\n    "XLK": "Technology",\n    "VOX": "Communication Services",\n    "XLY": "Consumer Discretionary",\n    "XLP": "Consumer Staples",\n    "XLI": "Industrials",\n    "XLB": "Materials",\n    "XLE": "Energy",\n    "XLF": "Financials",\n    "XLV": "Health Care",\n    "XLU": "Utilities",\n\n    # ------------------------------------------------\n    # 3. 테크 / 반도체 / 인터넷 / 클라우드\n    # ------------------------------------------------\n    "IGV": "Software",\n    "SOXX": "Semiconductors",\n    "XSD": "Semiconductors - Equal Weight",\n    "PSI": "Semiconductors - Dynamic",\n    "SKYY": "Cloud Computing",\n    "FDN": "Internet",\n    "PNQI": "Internet NASDAQ",\n    "SOCL": "Social Media",\n    "QTEC": "Tech - NASDAQ Equal Weight",\n    "TDIV": "Tech Dividend",\n\n    # ------------------------------------------------\n    # 4. 에너지 / 오일·가스 / MLP / 우라늄\n    # ------------------------------------------------\n    "XOP": "Oil & Gas Exploration",\n    "OIH": "Oil Services",\n    "IEZ": "Oil Equipment & Services",\n    "XES": "Oil & Gas Services",\n    "FCG": "Natural Gas",\n    "AMLP": "MLP Energy Infrastructure",\n    "MLPX": "MLP & Energy Infra",\n    "EMLP": "North American Energy Infra",\n    "ENFR": "Energy Infrastructure",\n    "URA": "Uranium",\n    "NLR": "Nuclear Energy",\n\n    # ------------------------------------------------\n    # 5. 금융 / 은행 / 보험 / 브로커 / BDC / PE\n    # ------------------------------------------------\n    "KBE": "Banks",\n    "KRE": "Regional Banks",\n    "IAI": "Broker-Dealers & Exchanges",\n    "KIE": "Insurance",\n    "IXG": "Global Financials",\n    "BIZD": "Business Development Companies",\n    "PSP": "Listed Private Equity",\n\n    # ------------------------------------------------\n    # 6. 헬스케어 / 의료기기 / 바이오\n    # ------------------------------------------------\n    "XBI": "Biotech Equal Weight",\n    "IBB": "Biotechnology",\n    "IHI": "Medical Devices",\n    "XHE": "Health Care Equipment",\n    "IHF": "Health Care Providers",\n    "XHS": "Health Care Services",\n    "IHE": "Pharmaceuticals",\n    "PJP": "Pharma Dynamic",\n\n    # ------------------------------------------------\n    # 7. 소비 / 리테일 / 주택 / 레저\n    # ------------------------------------------------\n    "XRT": "Retail",\n    "XHB": "Homebuilders",\n    "ITB": "Home Construction",\n    "PEJ": "Leisure & Entertainment",\n    "PBJ": "Food & Beverage",\n    "RXI": "Global Consumer Discretionary",\n    "CHIQ": "China Consumer",\n    "ECON": "Emerging Markets Consumer",\n    "INCO": "India Consumer",\n\n    # ------------------------------------------------\n    # 8. 산업 / 방산 / 운송 / 인프라 / 워터\n    # ------------------------------------------------\n    "ITA": "Aerospace & Defense",\n    "PPA": "Defense & Aerospace",\n    "XAR": "Aerospace & Defense Equal Weight",\n    "IYT": "Transportation",\n    "XTN": "Transportation Equal Weight",\n    "TOLZ": "Global Infrastructure",\n    "GII": "Global Infrastructure SPDR",\n    "EMIF": "Emerging Markets Infrastructure",\n    "CGW": "Global Water",\n    "FIW": "Water Resources",\n    "AIRR": "American Industrial Renaissance",\n\n    # ------------------------------------------------\n    # 9. 소재 / 자원 / 광물 / 금·은 / 농업\n    # ------------------------------------------------\n    "GNR": "Natural Resources",\n    "GUNR": "Global Upstream Natural Resources",\n    "HAP": "Natural Resources Producers",\n    "GDX": "Gold Miners",\n    "GDXJ": "Junior Gold Miners",\n    "SGDM": "Gold Miners - Sprott",\n    "SIL": "Silver Miners",\n    "SILJ": "Junior Silver Miners",\n    "SLVP": "Global Silver Miners",\n    "SLX": "Steel",\n    "COPX": "Copper Miners",\n    "REMX": "Rare Earth & Strategic Metals",\n    "PICK": "Global Metal & Mining",\n    "MOO": "Agribusiness",\n    "VEGI": "Agriculture Producers",\n    "WOOD": "Global Timber Forestry",\n    "CUT": "Timber & Forestry",\n\n    # ------------------------------------------------\n    # 10. 클린에너지 / 재생 / 그리드\n    # ------------------------------------------------\n    "ICLN": "Global Clean Energy",\n    "PBW": "Clean Energy - WilderHill",\n    "PBD": "Global Clean Energy",\n    "TAN": "Solar Energy",\n    "FAN": "Wind Energy",\n    "QCLN": "Clean Energy NASDAQ",\n    "GRID": "Smart Grid",\n\n    # ------------------------------------------------\n    # 11. 커뮤니케이션 / 글로벌 통신\n    # ------------------------------------------------\n    "IYZ": "Telecom",\n    "XTL": "Telecom SPDR",\n    "IXP": "Global Communication Services",\n\n    # ------------------------------------------------\n    # 12. 기타 테마\n    # ------------------------------------------------\n    "LIT": "Lithium & Battery Tech",\n    "SEA": "Shipping & Cargo",\n    "CARZ": "Global Auto",\n    "UFO": "Space & Satellite",\n    "ROBO" : "Robotics&Automation ETF"\n}\n\netf_list = list(industry_etfs.keys())\n\n# ----------------------------\n# 4. 데이터 다운로드 (250일 계산 안정화 위해 3년 권장)\n# ----------------------------\ndata = yf.download(etf_list, period="3y")[\'Close\'].sort_index()\n\nif \'SPY\' not in data.columns:\n    raise ValueError("SPY 데이터가 없습니다. 네트워크/티커 문제를 확인하세요.")\nspy = data[\'SPY\']\n\n# ----------------------------\n# 5. Mansfield RS 계산 함수 (6개월 = 126거래일)\n# ----------------------------\ndef compute_mansfield_rs(price_series, benchmark_series, ma_period):\n    relative = price_series / benchmark_series\n    ma = relative.rolling(window=ma_period, min_periods=ma_period).mean()\n    return ((relative / ma) - 1) * 100\n\ndef normalize_to_100_scale(x, scale=12):\n    return 100 * (1 / (1 + np.exp(-x / scale)))\n\n# ----------------------------\n# 6. RS 계산 실행 (6개월 = 126거래일)\n# ----------------------------\nRS_WINDOWS = [126]\nmansfield_rows = []\n\nfor ticker in etf_list:\n    if ticker == "SPY":\n        continue\n    if ticker not in data.columns:\n        continue\n\n    try:\n        price = data[ticker].dropna()\n        aligned = pd.concat([price, spy], axis=1, join=\'inner\')\n        aligned.columns = [\'etf\', \'spy\']\n\n        latest = {}\n        for win in RS_WINDOWS:\n            if len(aligned) >= win:\n                rs_series = compute_mansfield_rs(aligned[\'etf\'], aligned[\'spy\'], ma_period=win).dropna()\n                if not rs_series.empty:\n                    raw = float(rs_series.iloc[-1])\n                    latest[f"RS_{win}d"] = round(raw, 2)\n                    latest[f"Norm_RS_{win}d"] = round(normalize_to_100_scale(raw), 2)\n\n        raw_keys = [k for k in latest if k.startswith("RS_") and k.endswith("d")]\n        if not raw_keys:\n            continue\n\n        raw_values = [latest[k] for k in raw_keys]\n        rs_avg = round(sum(raw_values) / len(raw_values), 2)\n        norm_rs_avg = round(normalize_to_100_scale(rs_avg), 2)\n\n        row = {\n            "Ticker": ticker,\n            "Industry": industry_etfs.get(ticker, ""),\n            "RS_126d": np.nan,\n            "Norm_RS_126d": np.nan,\n            "RS_avg": rs_avg,\n            "Norm_RS_avg": norm_rs_avg,\n        }\n        for win in RS_WINDOWS:\n            if f"RS_{win}d" in latest:\n                row[f"RS_{win}d"] = latest[f"RS_{win}d"]\n                row[f"Norm_RS_{win}d"] = latest[f"Norm_RS_{win}d"]\n\n        mansfield_rows.append(row)\n\n    except Exception:\n        continue\n\nmansfield_df = pd.DataFrame(mansfield_rows).sort_values(by="Norm_RS_avg", ascending=False)\n\nprint("\\n📌 Mansfield RS 6개월(126거래일) 결과 (Norm_RS_avg 내림차순):")\ndisplay(mansfield_df)\n\nmansfield_df_70 = mansfield_df[mansfield_df["Norm_RS_avg"] >= 70].copy()\nif mansfield_df_70.empty:\n    print("\\n🚫 Normalized 6개월 RS ≥ 70 조건을 만족하는 ETF가 없습니다. 상위 10개를 보여드립니다:")\n    display(mansfield_df.head(10))\nelse:\n    print("\\n📌 Normalized 6개월 RS ≥ 70 (필터링):")\ndisplay(mansfield_df_70)\n\n# ------------------------------------------------------------\n# 6개월 절대수익률 + SPY 대비 6개월 상대수익률\n# ------------------------------------------------------------\nLOOKBACK_6M = 126\n\nreturn_6m = (\n    data / data.shift(LOOKBACK_6M) - 1\n)\n\nspy_return_6m = return_6m["SPY"]\n\nrelative_return_6m = return_6m.sub(\n    spy_return_6m,\n    axis=0\n)\n\nlatest_6m_date = return_6m.dropna(how="all").index[-1]\n\nsix_month_summary = pd.DataFrame({\n    "Ticker": [t for t in data.columns if t != "SPY"],\n})\n\nsix_month_summary["Industry"] = six_month_summary["Ticker"].map(\n    industry_etfs\n)\n\nsix_month_summary["6M_Return"] = six_month_summary["Ticker"].map(\n    return_6m.loc[latest_6m_date]\n)\n\nsix_month_summary["6M_RS_vs_SPY"] = six_month_summary["Ticker"].map(\n    relative_return_6m.loc[latest_6m_date]\n)\n\nsix_month_summary = (\n    six_month_summary\n    .dropna(subset=["6M_Return", "6M_RS_vs_SPY"])\n    .sort_values("6M_RS_vs_SPY", ascending=False)\n    .reset_index(drop=True)\n)\n\nsix_month_summary.index = six_month_summary.index + 1\nsix_month_summary.index.name = "Rank"\n\nprint(\n    f"\\n📌 기준일 {latest_6m_date.date()} "\n    f"미국 ETF 6개월 수익률 및 SPY 대비 RS"\n)\n\ndisplay(\n    six_month_summary.style.format({\n        "6M_Return": "{:.2%}",\n        "6M_RS_vs_SPY": "{:+.2%}",\n    })\n)\n\n# ----------------------------\n# 7. 변동성 조정 모멘텀 계산 함수 (+ 이동평균선 이탈 필터)\n#    ✅ FutureWarning 제거: pct_change(fill_method=None)\n#    ✅ vol=0 안전장치\n# ----------------------------\ndef calculate_risk_adjusted_momentum(\n    data,\n    period_6m=126,\n    last_n_days=10,\n    ma_filter_days=None,\n    top_n=20\n):\n    """\n    최근 6개월(126거래일) 누적수익률을\n    같은 기간 일간수익률 표준편차로 나눈 위험조정 모멘텀 점수.\n\n    score = 6개월 누적수익률 / 6개월 일간수익률 표준편차\n\n    ma_filter_days가 주어지면 해당 이동평균 하회 종목 제외.\n    """\n    daily_top_industries = {}\n    trading_days = data.index[-last_n_days:]\n\n    for day in trading_days:\n        end_idx = data.index.get_loc(day)\n        start_6m = max(0, end_idx - period_6m + 1)\n\n        window_6m = data.iloc[\n            start_6m:end_idx + 1\n        ]\n\n        if len(window_6m) < int(period_6m * 0.8):\n            daily_top_industries[day] = [None] * top_n\n            continue\n\n        # 6개월 누적수익률\n        returns_6m = (\n            window_6m.iloc[-1]\n            / window_6m.iloc[0]\n            - 1\n        )\n\n        # 6개월 일간수익률 변동성\n        daily_returns_6m = (\n            window_6m\n            .pct_change(fill_method=None)\n        )\n\n        vol_6m = (\n            daily_returns_6m\n            .std()\n            .replace(0, np.nan)\n        )\n\n        risk_adjusted_6m = (\n            returns_6m / vol_6m\n        )\n\n        # SPY는 벤치마크이므로 랭킹에서 제외\n        risk_adjusted_6m = risk_adjusted_6m.drop(\n            labels=["SPY"],\n            errors="ignore"\n        )\n\n        # 이동평균선 필터\n        if ma_filter_days is not None:\n            ma_ok = {}\n\n            for ticker in data.columns:\n                if ticker == "SPY":\n                    continue\n\n                series = (\n                    data[ticker]\n                    .iloc[:end_idx + 1]\n                    .dropna()\n                )\n\n                if len(series) < ma_filter_days:\n                    ma_ok[ticker] = False\n                else:\n                    ma_value = (\n                        series\n                        .rolling(ma_filter_days)\n                        .mean()\n                        .iloc[-1]\n                    )\n\n                    ma_ok[ticker] = bool(\n                        series.iloc[-1] >= ma_value\n                    )\n\n            ma_ok = pd.Series(ma_ok)\n\n            risk_adjusted_6m = risk_adjusted_6m[\n                ma_ok.reindex(\n                    risk_adjusted_6m.index\n                ).fillna(False)\n            ]\n\n        risk_adjusted_6m = (\n            risk_adjusted_6m\n            .dropna()\n            .sort_values(ascending=False)\n        )\n\n        top_list = (\n            risk_adjusted_6m\n            .head(top_n)\n            .index\n            .tolist()\n        )\n\n        top_names = [\n            f"{ticker} ({industry_etfs.get(ticker, \'\')})"\n            for ticker in top_list\n        ]\n\n        top_names += [None] * max(\n            0,\n            top_n - len(top_names)\n        )\n\n        daily_top_industries[day] = top_names\n\n    df = pd.DataFrame.from_dict(\n        daily_top_industries,\n        orient="index",\n        columns=[\n            f"Top {i+1}"\n            for i in range(top_n)\n        ]\n    )\n\n    df.index.name = "Date"\n    return df\n\n# ----------------------------\n# 8. 모멘텀 결과 출력 (Top 20 기준)\n# ----------------------------\nprint("\\n📌 6개월 변동성 조정 모멘텀 기준 상위 20 ETF (최근 10일 기준, 전체):")\nmomentum_df = calculate_risk_adjusted_momentum(data, last_n_days=10, top_n=20)\ndisplay(momentum_df)\n\nprint("\\n📌 6개월 변동성 조정 모멘텀 상위 20 ETF (10일선 이상):")\nmomentum_df_ma10 = calculate_risk_adjusted_momentum(data, last_n_days=10, ma_filter_days=10, top_n=20)\ndisplay(momentum_df_ma10)\n\nprint("\\n📌 6개월 변동성 조정 모멘텀 상위 20 ETF (20일선 이상):")\nmomentum_df_ma20 = calculate_risk_adjusted_momentum(data, last_n_days=10, ma_filter_days=20, top_n=20)\ndisplay(momentum_df_ma20)\n\nprint("\\n📌 6개월 변동성 조정 모멘텀 상위 20 ETF (60일선 이상):")\nmomentum_df_ma60 = calculate_risk_adjusted_momentum(data, last_n_days=10, ma_filter_days=60, top_n=20)\ndisplay(momentum_df_ma60)\n\n# ============================================================\n# 9. Sortino: 10일선 이상 기준만 계산\n#    - ETR Comfort 출력/기존 11~12번 추가 분석은 삭제\n#    - 최종 30일 초과 이격도 분석은 6개월 Sortino 10일선 이상 리스트 기준\n# ============================================================\n\nimport logging\nlogging.getLogger(\'matplotlib.font_manager\').setLevel(logging.ERROR)\nplt.rcParams[\'axes.unicode_minus\'] = False\n\n\ndef sortino_from_returns(ret: pd.Series, mar: float = 0.0, periods_per_year: int = 252) -> float:\n    """Sortino Ratio, annualized."""\n    ret = ret.dropna()\n    if len(ret) < 5:\n        return np.nan\n\n    mar_daily = (1 + mar) ** (1 / periods_per_year) - 1\n    excess = ret - mar_daily\n    downside = excess[excess < 0]\n\n    if len(downside) < 5:\n        return np.nan\n\n    downside_dev = downside.std(ddof=1) * np.sqrt(periods_per_year)\n    if downside_dev == 0 or np.isnan(downside_dev):\n        return np.nan\n\n    annual_excess = excess.mean() * periods_per_year\n    return float(annual_excess / downside_dev)\n\n\ndef ma_ok_mask(close_df: pd.DataFrame, end_idx: int, ma_days: int) -> pd.Series:\n    """end_idx 시점에서 종가 >= MA(ma_days)이면 True."""\n    ok = {}\n    for t in close_df.columns:\n        s = close_df[t].iloc[:end_idx + 1].dropna()\n        if len(s) < ma_days:\n            ok[t] = False\n        else:\n            ma = s.rolling(ma_days).mean().iloc[-1]\n            ok[t] = bool(s.iloc[-1] >= ma)\n    return pd.Series(ok)\n\n\ndef rank_sortino_ma_filter(\n    close_df: pd.DataFrame,\n    period_6m: int = 126,\n    last_n_days: int = 10,\n    ma_filter_days: int = 10,\n    top_n: int = 20,\n    periods_per_year: int = 252,\n    mar: float = 0.0,\n):\n    """\n    최근 6개월(126거래일) Sortino를 계산해 순위를 매깁니다.\n    ma_filter_days가 주어지면 해당 날짜 기준\n    종가 >= 이동평균선인 ETF만 통과합니다.\n    """\n    daily_top = {}\n    trading_days = (\n        close_df\n        .dropna(how="all")\n        .index[-last_n_days:]\n    )\n\n    for day in trading_days:\n        end_idx = close_df.index.get_loc(day)\n\n        ok = ma_ok_mask(\n            close_df,\n            end_idx=end_idx,\n            ma_days=ma_filter_days\n        )\n\n        scores = {}\n\n        for ticker in close_df.columns:\n            if not ok.get(ticker, False):\n                continue\n\n            start_idx = max(\n                0,\n                end_idx - period_6m + 1\n            )\n\n            prices_6m = (\n                close_df[ticker]\n                .iloc[start_idx:end_idx + 1]\n                .dropna()\n            )\n\n            if len(prices_6m) < max(\n                20,\n                int(period_6m * 0.8)\n            ):\n                continue\n\n            returns_6m = (\n                prices_6m\n                .pct_change(fill_method=None)\n                .dropna()\n            )\n\n            score = sortino_from_returns(\n                returns_6m,\n                mar=mar,\n                periods_per_year=periods_per_year\n            )\n\n            if pd.notna(score):\n                scores[ticker] = float(score)\n\n        if len(scores) == 0:\n            daily_top[day] = [None] * top_n\n            continue\n\n        ranked = (\n            pd.Series(scores)\n            .sort_values(ascending=False)\n            .head(top_n)\n            .index\n            .tolist()\n        )\n\n        row = [\n            f"{ticker} ({industry_etfs.get(ticker, \'\')})"\n            for ticker in ranked\n        ]\n\n        row += [None] * max(\n            0,\n            top_n - len(row)\n        )\n\n        daily_top[day] = row\n\n    out = pd.DataFrame.from_dict(\n        daily_top,\n        orient="index",\n        columns=[\n            f"Top {i+1}"\n            for i in range(top_n)\n        ]\n    )\n\n    out.index.name = "Date"\n    return out\n\n\n# SPY는 벤치마크이므로 업종 랭킹에서는 제외\nsector_data = data.drop(columns=["SPY"], errors="ignore").copy()\n\nprint("\\n📌 6개월 Sortino 상위 20 ETF (최근 10일, 10일선 이상):")\nsortino_ma10 = rank_sortino_ma_filter(\n    sector_data,\n    last_n_days=10,\n    ma_filter_days=10,\n    top_n=20\n)\ndisplay(sortino_ma10)\n\nprint("\\n📌 6개월 Sortino 상위 20 ETF (최근 10일, 20일선 이상):")\nsortino_ma20 = rank_sortino_ma_filter(\n    sector_data,\n    last_n_days=10,\n    ma_filter_days=20,\n    top_n=20\n)\ndisplay(sortino_ma20)\n\nprint("\\n📌 6개월 Sortino 상위 20 ETF (최근 10일, 10주(50일선) 이상):")\nsortino_ma50 = rank_sortino_ma_filter(\n    sector_data,\n    last_n_days=10,\n    ma_filter_days=50,\n    top_n=20\n)\ndisplay(sortino_ma50)\n\n\n# ============================================================\n# 10. 최종 분석\n#     6개월 Sortino 10일선 이상 ETF 기준\n#     30일 초과 이격도 + 최근 247거래일 97% 초과 이격도\n#\n# 계산 기준:\n# - 30일 초과 이격도 = (현재가 / MA30 - 1) * 100\n# - 최근247거래일97구간초과이격도 = 최근 247거래일 30일 초과 이격도의 97% 분위수\n# - 97구간대비현재위치 = 현재30일초과이격도 / 최근247거래일97구간초과이격도 * 100\n#\n# 표는 한글, 그래프는 영문 제목만 사용해서 Matplotlib 한글 폰트 경고를 방지\n# ============================================================\n\n\ndef _extract_ticker_from_label(x):\n    """\'SOXX (Semiconductors)\' 형태에서 SOXX만 추출."""\n    if pd.isna(x):\n        return None\n    return str(x).split(" ")[0].strip()\n\n\ndef build_sortino_ma10_gap247_p97_summary(\n    close_df: pd.DataFrame,\n    sortino_table: pd.DataFrame,\n    industry_map: dict,\n    ma_days: int = 30,\n    lookback_days: int = 247,\n    percentile: float = 0.97,\n    top_n: int = 20,\n):\n    latest_row = sortino_table.iloc[-1].dropna().tolist()\n    tickers = [_extract_ticker_from_label(x) for x in latest_row]\n    tickers = [x for x in tickers if x in close_df.columns]\n\n    if top_n is not None:\n        tickers = tickers[:top_n]\n\n    rows = []\n\n    for rank_no, ticker in enumerate(tickers, start=1):\n        price = close_df[ticker].dropna()\n        if len(price) < ma_days + 20:\n            continue\n\n        ma30 = price.rolling(ma_days).mean()\n        gap_excess = (price / ma30 - 1) * 100\n        gap_excess = gap_excess.dropna()\n\n        if len(gap_excess) < 20:\n            continue\n\n        hist = gap_excess.tail(lookback_days)\n        current_excess = float(gap_excess.iloc[-1])\n        p97_excess = float(hist.quantile(percentile))\n\n        if pd.notna(p97_excess) and p97_excess != 0:\n            heat_ratio = current_excess / p97_excess * 100\n        else:\n            heat_ratio = np.nan\n\n        rows.append({\n            "Sortino순위": rank_no,\n            "Ticker": ticker,\n            "Industry": industry_map.get(ticker, ""),\n            "Date": gap_excess.index[-1].date(),\n            "현재30일초과이격도": round(current_excess, 2),\n            "최근247거래일97구간초과이격도": round(p97_excess, 2),\n            "97구간대비현재위치": round(heat_ratio, 1) if pd.notna(heat_ratio) else np.nan,\n            "사용거래일수": len(hist),\n        })\n\n    out = pd.DataFrame(rows)\n\n    if not out.empty:\n        out = out[[\n            "Sortino순위",\n            "Ticker",\n            "Industry",\n            "Date",\n            "현재30일초과이격도",\n            "최근247거래일97구간초과이격도",\n            "97구간대비현재위치",\n            "사용거래일수",\n        ]]\n\n    return out\n\n\ndef plot_sortino_ma10_gap247_p97_graphs(\n    close_df: pd.DataFrame,\n    summary_df: pd.DataFrame,\n    ma_days: int = 30,\n    lookback_days: int = 247,\n    figsize=(16, 4),\n    bar_alpha: float = 0.15,\n):\n    if summary_df.empty:\n        print("그래프로 출력할 ETF가 없습니다.")\n        return\n\n    for _, row in summary_df.iterrows():\n        ticker = row["Ticker"]\n        industry = row["Industry"]\n\n        price = close_df[ticker].dropna()\n        ma30 = price.rolling(ma_days).mean()\n        gap_excess = (price / ma30 - 1) * 100\n\n        plot_df = pd.DataFrame({\n            "Price": price,\n            "MA30": ma30,\n            "GapExcess30": gap_excess,\n        }).dropna()\n\n        if plot_df.empty:\n            continue\n\n        fig, ax1 = plt.subplots(figsize=figsize)\n        ax2 = ax1.twinx()\n\n        # 오른쪽 축: 30일 초과 이격도 막대\n        ax2.bar(\n            plot_df.index,\n            plot_df["GapExcess30"],\n            alpha=bar_alpha,\n            width=1.5,\n            label="GapExcess30",\n            zorder=1,\n        )\n\n        # 97% 구간 기준선\n        p97 = row["최근247거래일97구간초과이격도"]\n        if pd.notna(p97):\n            ax2.axhline(\n                p97,\n                linestyle="--",\n                linewidth=1.2,\n                label="P97_247D",\n                zorder=2,\n            )\n\n        # 왼쪽 축을 앞으로 가져오기\n        ax1.set_zorder(ax2.get_zorder() + 1)\n        ax1.patch.set_visible(False)\n\n        # 왼쪽 축: 가격 + MA30\n        ax1.plot(\n            plot_df.index,\n            plot_df["Price"],\n            linewidth=2.8,\n            label=ticker,\n            zorder=10,\n        )\n\n        ax1.plot(\n            plot_df.index,\n            plot_df["MA30"],\n            linewidth=2.4,\n            label="MA30",\n            zorder=9,\n        )\n\n        ax1.grid(True, alpha=0.25, zorder=0)\n\n        # ------------------------------------------------------------\n        # 제목/수치 정보는 그래프 안쪽 좌측 상단에 표시\n        # - 범례와 제목이 겹치지 않도록 set_title은 사용하지 않음\n        # - 그래프 텍스트는 영문만 사용해서 Matplotlib 한글 폰트 경고 방지\n        # ------------------------------------------------------------\n        info_text_1 = f"#{int(row[\'Sortino순위\'])} {ticker} | {industry}"\n        info_text_2 = (\n            f"GapExcess30={row[\'현재30일초과이격도\']:.2f} | "\n            f"P97_247D={row[\'최근247거래일97구간초과이격도\']:.2f} | "\n            f"Heat={row[\'97구간대비현재위치\']:.1f}"\n        )\n\n        ax1.text(\n            0.01,\n            0.96,\n            info_text_1,\n            transform=ax1.transAxes,\n            fontsize=12,\n            fontweight="bold",\n            va="top",\n            ha="left",\n            bbox=dict(facecolor="white", alpha=0.75, edgecolor="none"),\n            zorder=20,\n        )\n\n        ax1.text(\n            0.01,\n            0.88,\n            info_text_2,\n            transform=ax1.transAxes,\n            fontsize=10.5,\n            fontweight="bold",\n            va="top",\n            ha="left",\n            bbox=dict(facecolor="white", alpha=0.75, edgecolor="none"),\n            zorder=20,\n        )\n\n        ax1.set_ylabel("Price")\n        ax2.set_ylabel("Gap excess")\n\n        lines1, labels1 = ax1.get_legend_handles_labels()\n        lines2, labels2 = ax2.get_legend_handles_labels()\n\n        # 범례는 그래프 위쪽에 한 줄로 배치하되, 제목을 없앴기 때문에 겹치지 않음\n        ax1.legend(\n            lines2 + lines1,\n            labels2 + labels1,\n            loc="upper center",\n            bbox_to_anchor=(0.5, 1.10),\n            ncol=4,\n            frameon=False,\n            fontsize=10,\n        )\n\n        plt.tight_layout()\n        plt.show()\n\n\nsortino_ma10_gap247_p97_summary = build_sortino_ma10_gap247_p97_summary(\n    close_df=sector_data,\n    sortino_table=sortino_ma10,\n    industry_map=industry_etfs,\n    ma_days=30,\n    lookback_days=247,\n    percentile=0.97,\n    top_n=20,\n)\n\nprint("\\n📌 최종 분석: 미국 업종 ETF / 6개월 Sortino 10일선 이상 기준")\nprint(" - 현재30일초과이격도: (현재가 / MA30 - 1) * 100")\nprint(" - 최근247거래일97구간초과이격도: 최근 247거래일 기준 97% 분위수")\nprint(" - 97구간대비현재위치: 100 이상이면 최근 247거래일 97% 구간 초과")\ndisplay(sortino_ma10_gap247_p97_summary)\n\nplot_sortino_ma10_gap247_p97_graphs(\n    close_df=sector_data,\n    summary_df=sortino_ma10_gap247_p97_summary,\n    ma_days=30,\n    lookback_days=247,\n    figsize=(16, 4),\n    bar_alpha=0.15,\n)\n\n# ============================================================\n# 11. 4주 / 13주 / 26주 / 52주 이동평균 정배열 ETF\n#\n# 일봉 데이터 기준:\n# 4주  = 20거래일\n# 13주 = 65거래일\n# 26주 = 130거래일\n# 52주 = 260거래일\n#\n# 완전 정배열:\n# Price > MA20 > MA65 > MA130 > MA260\n#\n# 이평 정배열:\n# MA20 > MA65 > MA130 > MA260\n#\n# 추가:\n# - 정배열 시작일\n# - 현재까지 연속 유지 거래일\n# - 달력일 기준 유지기간\n# ============================================================\n\nMA_4W = 20\nMA_13W = 65\nMA_26W = 130\nMA_52W = 260\n\n\ndef _current_true_streak(mask: pd.Series):\n    """\n    최신일 기준 True가 연속으로 이어지는 거래일 수와 시작일 계산\n    """\n    mask = mask.dropna().astype(bool)\n\n    if mask.empty or not bool(mask.iloc[-1]):\n        return 0, pd.NaT\n\n    arr = mask.to_numpy()\n    false_positions = np.flatnonzero(~arr)\n\n    if len(false_positions) == 0:\n        start_pos = 0\n    else:\n        start_pos = false_positions[-1] + 1\n\n    streak_days = len(mask) - start_pos\n    start_date = mask.index[start_pos]\n\n    return int(streak_days), start_date\n\n\ndef get_us_etf_weekly_ma_alignment(\n    price_df: pd.DataFrame,\n    industry_map: dict\n) -> pd.DataFrame:\n    """\n    미국 ETF별 최신 유효 시점에서\n    4주(20일), 13주(65일), 26주(130일), 52주(260일)\n    이동평균 정배열 여부와 현재 연속 유지기간을 계산합니다.\n    """\n\n    price_df = price_df.sort_index().copy()\n\n    ma4 = price_df.rolling(\n        window=MA_4W,\n        min_periods=MA_4W\n    ).mean()\n\n    ma13 = price_df.rolling(\n        window=MA_13W,\n        min_periods=MA_13W\n    ).mean()\n\n    ma26 = price_df.rolling(\n        window=MA_26W,\n        min_periods=MA_26W\n    ).mean()\n\n    ma52 = price_df.rolling(\n        window=MA_52W,\n        min_periods=MA_52W\n    ).mean()\n\n    rows = []\n\n    for ticker in price_df.columns:\n\n        # SPY는 벤치마크이므로 정배열 업종 리스트에서 제외\n        if ticker == "SPY":\n            continue\n\n        temp = pd.DataFrame({\n            "Price": price_df[ticker],\n            "MA4W": ma4[ticker],\n            "MA13W": ma13[ticker],\n            "MA26W": ma26[ticker],\n            "MA52W": ma52[ticker],\n        }).dropna()\n\n        if temp.empty:\n            continue\n\n        # 날짜별 이평 정배열 상태\n        ma_mask = (\n            (temp["MA4W"] > temp["MA13W"])\n            & (temp["MA13W"] > temp["MA26W"])\n            & (temp["MA26W"] > temp["MA52W"])\n        )\n\n        # 날짜별 완전 정배열 상태\n        full_mask = (\n            (temp["Price"] > temp["MA4W"])\n            & ma_mask\n        )\n\n        latest_date = temp.index[-1]\n        row = temp.iloc[-1]\n\n        ma_alignment = bool(ma_mask.iloc[-1])\n        full_alignment = bool(full_mask.iloc[-1])\n\n        ma_streak_days, ma_start_date = _current_true_streak(ma_mask)\n        full_streak_days, full_start_date = _current_true_streak(full_mask)\n\n        ma_calendar_days = (\n            (latest_date - ma_start_date).days + 1\n            if ma_alignment and pd.notna(ma_start_date)\n            else 0\n        )\n\n        full_calendar_days = (\n            (latest_date - full_start_date).days + 1\n            if full_alignment and pd.notna(full_start_date)\n            else 0\n        )\n\n        gap_price_4w = (\n            row["Price"] / row["MA4W"] - 1\n        ) * 100\n\n        gap_4w_13w = (\n            row["MA4W"] / row["MA13W"] - 1\n        ) * 100\n\n        gap_13w_26w = (\n            row["MA13W"] / row["MA26W"] - 1\n        ) * 100\n\n        gap_26w_52w = (\n            row["MA26W"] / row["MA52W"] - 1\n        ) * 100\n\n        alignment_strength = (\n            gap_price_4w\n            + gap_4w_13w\n            + gap_13w_26w\n            + gap_26w_52w\n        )\n\n        rows.append({\n            "Ticker": ticker,\n            "Industry": industry_map.get(ticker, ""),\n            "Date": latest_date.date(),\n\n            "Price": float(row["Price"]),\n            "MA4W": float(row["MA4W"]),\n            "MA13W": float(row["MA13W"]),\n            "MA26W": float(row["MA26W"]),\n            "MA52W": float(row["MA52W"]),\n\n            "Price>4W": bool(row["Price"] > row["MA4W"]),\n            "4W>13W": bool(row["MA4W"] > row["MA13W"]),\n            "13W>26W": bool(row["MA13W"] > row["MA26W"]),\n            "26W>52W": bool(row["MA26W"] > row["MA52W"]),\n\n            "MA_Alignment": ma_alignment,\n            "Full_Alignment": full_alignment,\n\n            "MA_Alignment_Start": (\n                ma_start_date.date()\n                if ma_alignment and pd.notna(ma_start_date)\n                else None\n            ),\n            "MA_Alignment_TradingDays": ma_streak_days,\n            "MA_Alignment_CalendarDays": ma_calendar_days,\n\n            "Full_Alignment_Start": (\n                full_start_date.date()\n                if full_alignment and pd.notna(full_start_date)\n                else None\n            ),\n            "Full_Alignment_TradingDays": full_streak_days,\n            "Full_Alignment_CalendarDays": full_calendar_days,\n\n            "Price_4W_Gap(%)": float(gap_price_4w),\n            "4W_13W_Gap(%)": float(gap_4w_13w),\n            "13W_26W_Gap(%)": float(gap_13w_26w),\n            "26W_52W_Gap(%)": float(gap_26w_52w),\n            "Alignment_Strength": float(alignment_strength),\n        })\n\n    out = pd.DataFrame(rows)\n\n    if out.empty:\n        return out\n\n    return (\n        out\n        .sort_values(\n            by=[\n                "Full_Alignment",\n                "Full_Alignment_TradingDays",\n                "Alignment_Strength"\n            ],\n            ascending=[False, False, False]\n        )\n        .reset_index(drop=True)\n    )\n\n\n# ------------------------------------------------------------\n# 정배열 계산\n# ------------------------------------------------------------\n\nus_weekly_alignment_df = get_us_etf_weekly_ma_alignment(\n    price_df=data,\n    industry_map=industry_etfs\n)\n\n\nif us_weekly_alignment_df.empty:\n\n    print(\n        "\\n⚠️ 4주·13주·26주·52주 정배열을 계산할 수 있는 "\n        "충분한 ETF 데이터가 없습니다."\n    )\n\nelse:\n\n    # --------------------------------------------------------\n    # ① 완전 정배열\n    # Price > 4W > 13W > 26W > 52W\n    # --------------------------------------------------------\n\n    us_full_alignment_df = (\n        us_weekly_alignment_df[\n            us_weekly_alignment_df["Full_Alignment"]\n        ]\n        .copy()\n        .sort_values(\n            by=[\n                "Full_Alignment_TradingDays",\n                "Alignment_Strength"\n            ],\n            ascending=[False, False]\n        )\n        .reset_index(drop=True)\n    )\n\n    us_full_alignment_df.index += 1\n    us_full_alignment_df.index.name = "Rank"\n\n    print(\n        "\\n📌 미국 ETF 4주·13주·26주·52주 완전 정배열"\n        "\\n   Price > 4W > 13W > 26W > 52W"\n        "\\n   ※ 정배열 시작일과 연속 유지기간 포함"\n    )\n\n    if us_full_alignment_df.empty:\n        print("해당 ETF가 없습니다.")\n    else:\n        display(\n            us_full_alignment_df[\n                [\n                    "Ticker",\n                    "Industry",\n                    "Date",\n                    "Full_Alignment_Start",\n                    "Full_Alignment_TradingDays",\n                    "Full_Alignment_CalendarDays",\n                    "Price",\n                    "MA4W",\n                    "MA13W",\n                    "MA26W",\n                    "MA52W",\n                    "Price_4W_Gap(%)",\n                    "4W_13W_Gap(%)",\n                    "13W_26W_Gap(%)",\n                    "26W_52W_Gap(%)",\n                    "Alignment_Strength",\n                ]\n            ].style.format({\n                "Price": "{:,.2f}",\n                "MA4W": "{:,.2f}",\n                "MA13W": "{:,.2f}",\n                "MA26W": "{:,.2f}",\n                "MA52W": "{:,.2f}",\n                "Price_4W_Gap(%)": "{:+.2f}%",\n                "4W_13W_Gap(%)": "{:+.2f}%",\n                "13W_26W_Gap(%)": "{:+.2f}%",\n                "26W_52W_Gap(%)": "{:+.2f}%",\n                "Alignment_Strength": "{:.2f}",\n            })\n        )\n\n\n    # --------------------------------------------------------\n    # ② 이평 정배열\n    # 4W > 13W > 26W > 52W\n    # --------------------------------------------------------\n\n    us_ma_alignment_df = (\n        us_weekly_alignment_df[\n            us_weekly_alignment_df["MA_Alignment"]\n        ]\n        .copy()\n        .sort_values(\n            by=[\n                "MA_Alignment_TradingDays",\n                "Alignment_Strength"\n            ],\n            ascending=[False, False]\n        )\n        .reset_index(drop=True)\n    )\n\n    us_ma_alignment_df.index += 1\n    us_ma_alignment_df.index.name = "Rank"\n\n    print(\n        "\\n📌 미국 ETF 이동평균 정배열"\n        "\\n   4W > 13W > 26W > 52W"\n        "\\n   ※ 정배열 시작일과 연속 유지기간 포함"\n    )\n\n    if us_ma_alignment_df.empty:\n        print("해당 ETF가 없습니다.")\n    else:\n        display(\n            us_ma_alignment_df[\n                [\n                    "Ticker",\n                    "Industry",\n                    "Date",\n                    "MA_Alignment_Start",\n                    "MA_Alignment_TradingDays",\n                    "MA_Alignment_CalendarDays",\n                    "Price",\n                    "MA4W",\n                    "MA13W",\n                    "MA26W",\n                    "MA52W",\n                    "Price>4W",\n                    "Alignment_Strength",\n                ]\n            ].style.format({\n                "Price": "{:,.2f}",\n                "MA4W": "{:,.2f}",\n                "MA13W": "{:,.2f}",\n                "MA26W": "{:,.2f}",\n                "MA52W": "{:,.2f}",\n                "Alignment_Strength": "{:.2f}",\n            })\n        )\n\n\n    # --------------------------------------------------------\n    # ③ 전체 ETF 정배열 상태표\n    # --------------------------------------------------------\n\n    print("\\n📌 전체 미국 ETF 정배열 상태")\n\n    display(\n        us_weekly_alignment_df[\n            [\n                "Ticker",\n                "Industry",\n                "Date",\n                "MA_Alignment",\n                "MA_Alignment_Start",\n                "MA_Alignment_TradingDays",\n                "Full_Alignment",\n                "Full_Alignment_Start",\n                "Full_Alignment_TradingDays",\n                "Alignment_Strength",\n            ]\n        ].style.format({\n            "Alignment_Strength": "{:.2f}",\n        })\n    )\n\n\n    # --------------------------------------------------------\n    # ④ ETF 이름 + 유지기간 간단 출력\n    # --------------------------------------------------------\n\n    print(\n        "\\n🔥 완전 정배열 ETF "\n        "(Price > 4W > 13W > 26W > 52W)"\n    )\n\n    if len(us_full_alignment_df) > 0:\n\n        for i, (_, row) in enumerate(\n            us_full_alignment_df.iterrows(),\n            start=1\n        ):\n            print(\n                f"{i}. {row[\'Ticker\']} "\n                f"({row[\'Industry\']}) | "\n                f"{row[\'Full_Alignment_Start\']}부터 | "\n                f"{int(row[\'Full_Alignment_TradingDays\'])}거래일 유지"\n            )\n\n    else:\n        print("없음")\n\n\n    print(\n        "\\n📈 이평 정배열 ETF "\n        "(4W > 13W > 26W > 52W)"\n    )\n\n    if len(us_ma_alignment_df) > 0:\n\n        for i, (_, row) in enumerate(\n            us_ma_alignment_df.iterrows(),\n            start=1\n        ):\n            print(\n                f"{i}. {row[\'Ticker\']} "\n                f"({row[\'Industry\']}) | "\n                f"{row[\'MA_Alignment_Start\']}부터 | "\n                f"{int(row[\'MA_Alignment_TradingDays\'])}거래일 유지"\n            )\n\n    else:\n        print("없음")\n\n\n    # --------------------------------------------------------\n    # ⑤ 정배열 현황 요약\n    # --------------------------------------------------------\n\n    print(\n        f"\\n📊 미국 ETF 정배열 현황"\n        f"\\n- 완전 정배열: {len(us_full_alignment_df)}개"\n        f"\\n- 이평 정배열: {len(us_ma_alignment_df)}개"\n        f"\\n- 분석 가능 전체 ETF: {len(us_weekly_alignment_df)}개"\n    )'

def run_korea_sector(excel_bytes):
    # 국내 코드는 업로드한 엑셀 bytes만 사용
    src = KR_SECTOR_SRC
    buf=io.StringIO(); shown=[]; figs=[]
    def _display(obj):
        shown.append(obj.data if hasattr(obj,"data") else obj)
    old_show=plt.show
    def _show(*args, **kwargs):
        figs.append(plt.gcf())
    plt.show=_show
    ns={"display":_display, "EXCEL_BYTES":excel_bytes}
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            exec(src,ns,ns)
        ok=True
    except Exception:
        ok=False; buf.write("\n"+traceback.format_exc())
    finally:
        plt.show=old_show
    return ok,ns,buf.getvalue(),shown,figs

def run_us_sector():
    return run_source(US_SECTOR_SRC)

def check_admin_password():
    """관리자 비밀번호는 Streamlit Secrets의 ADMIN_PASSWORD에서 읽습니다."""
    if "admin_authenticated" not in st.session_state:
        st.session_state.admin_authenticated = False

    with st.sidebar:
        st.markdown("### 🔐 관리자")
        if st.session_state.admin_authenticated:
            st.success("관리자 모드")
            if st.button("관리자 로그아웃", key="admin_logout"):
                st.session_state.admin_authenticated = False
                st.rerun()
        else:
            pw = st.text_input("관리자 비밀번호", type="password", key="admin_pw")
            if st.button("관리자 로그인", key="admin_login"):
                try:
                    expected = st.secrets["ADMIN_PASSWORD"]
                except Exception:
                    st.error("Streamlit Secrets에 ADMIN_PASSWORD를 먼저 등록하세요.")
                    return False
                if pw == expected:
                    st.session_state.admin_authenticated = True
                    st.rerun()
                else:
                    st.error("비밀번호가 맞지 않습니다.")
    return st.session_state.admin_authenticated

